begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('48000000-0000-4000-8000-000000000001','cert-vet@example.test','{}'),('48000000-0000-4000-8000-000000000002','cert-staff@example.test','{}');
insert into public.user_roles(user_id,role) values('48000000-0000-4000-8000-000000000001','DVM') on conflict do nothing;
create temp table fx(k text primary key,id uuid); grant all on fx to authenticated;
create temp table requests(k text primary key,v jsonb); grant all on requests to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"48000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into fx select 'client',id from public.save_client(auth.uid(),null,null,'Certificate','Family','3035550100',null,'EMAIL','123 Test St, Boulder CO',null);
insert into fx select 'pet',id from public.save_patient(null,(select id from fx where k='client'),null,'Certificate dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
insert into fx select 'other',id from public.save_patient(null,(select id from fx where k='client'),null,'Other dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}')$$,'42501','Verified veterinarian credentials and clinical acceptance are required','DVM role alone does not establish verified credentials');
reset role;
insert into public.certificate_issuers(user_id,full_name,license_number,license_state,license_expires_on,practice_name,practice_address,practice_phone,verified_at,verification_reference,clinical_acceptance_at,active) values('48000000-0000-4000-8000-000000000001','Dr Test','TEST-ONLY','CO',current_date+365,'Test practice','2619 Spruce Street, Boulder CO','3035550199',now(),'SYNTHETIC TEST VERIFICATION',now(),true);
set local role authenticated;
insert into fx select 'product',id from public.save_catalog_product(null,null,'Test rabies vaccine','vaccine','Test manufacturer','dose',3000,true);
select public.receive_inventory('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002',(select id from fx where k='product'),'TEST-LOT',current_date+365,'Clinic',10,'Synthetic test stock');
select public.create_billing_invoice('49000000-0000-4000-8000-000000000003',(select id from fx where k='client'));
insert into requests values('live',jsonb_build_object('pet_id',(select id from fx where k='pet'),'lot_id','49000000-0000-4000-8000-000000000002','invoice_id','49000000-0000-4000-8000-000000000003','quantity',1,'dose','1 mL','route','SC','site','right rear leg','veterinarian','Dr Test','veterinarian_license','TEST-ONLY','administered_at',now(),'next_due_on',current_date+365));
select public.record_patient_treatment('49000000-0000-4000-8000-000000000004',(select v from requests where k='live'));
insert into requests values('details','{"administrator":"Test technician","rabies_tag_number":"TEST-TAG","usda_duration":"1 year","vaccine_type":"Killed virus","size_description":"20–50 lb","initial_or_booster":"initial","owner_business_phone_unavailable":true,"supervision_attested":true}');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004','{}')$$,'23514',null,'Missing rabies metadata rejected');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='other'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'))$$,'23514','No eligible vaccination records','Cross-patient rabies source rejected');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v||'{"rabies_tag_number":true}' from requests where k='details'))$$,'23514','Invalid certificate detail type','Metadata must have correct types');
insert into requests select 'preview',public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'));
select is((select v#>>'{vaccinations,0,manufacturer}' from requests where k='preview'),'Test manufacturer','Preview uses frozen manufacturer');
select throws_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'),(select v from requests where k='preview'),'Dr Test',false)$$,'23514',null,'Explicit signature attestation required');
select throws_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'),(select v from requests where k='preview'),'Other Vet',true)$$,'23514',null,'Cannot substitute signer');
select lives_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'),(select v from requests where k='preview'),'Dr Test',true)$$,'Issue explicitly signed certificate');
select lives_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'),(select v from requests where k='preview'),'Dr Test',true)$$,'Retry returns same issued certificate');
select is((select count(*) from public.vaccine_certificates),1::bigint,'Exactly one issued snapshot');
select throws_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000005',(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v||'{"rabies_tag_number":"different"}' from requests where k='details'),(select v from requests where k='preview'),'Dr Test',true)$$,'23514','Certificate identifier already used','Retry payload cannot change');
select public.save_patient((select id from fx where k='pet'),(select id from fx where k='client'),1,'Renamed dog','Dog','Mixed','2020-01-01','exact','Brown','female','neutered',null,null,null);
select is((select snapshot#>>'{patient,name}' from public.vaccine_certificates),'Certificate dog','Issued identity never follows later patient edits');
select throws_ok($$select public.issue_vaccine_certificate(gen_random_uuid(),(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'),(select v from requests where k='preview'),'Dr Test',true)$$,'40001',null,'Stale reviewed identity cannot issue');
select throws_ok($$update public.vaccine_certificates set signature_name='Impersonator'$$,'42501',null,'Direct certificate rewriting denied');
select throws_ok($$delete from public.vaccine_certificates$$,'42501',null,'Direct certificate deletion denied');
select throws_ok($$update public.certificate_issuers set active=true$$,'42501',null,'Staff cannot self-verify credentials');
update requests set v=public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details')) where k='preview';
select lives_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000006',(select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'),(select v from requests where k='preview'),'Dr Test',true,'49000000-0000-4000-8000-000000000005','Patient name corrected')$$,'Reasoned reissue creates a new certificate');
select is((select count(*) from public.vaccine_certificates),2::bigint,'Reissue preserves original');
select is((select kind from public.vaccine_certificate_events where certificate_id='49000000-0000-4000-8000-000000000005'),'superseded','Original carries append-only superseded event');
select lives_ok($$select public.void_vaccine_certificate('49000000-0000-4000-8000-000000000007','49000000-0000-4000-8000-000000000006','Review needed')$$,'Explicit void event');
select lives_ok($$select public.void_vaccine_certificate('49000000-0000-4000-8000-000000000007','49000000-0000-4000-8000-000000000006','Review needed')$$,'Void retry idempotent');
select lives_ok($$select public.correct_patient_treatment('49000000-0000-4000-8000-000000000008','49000000-0000-4000-8000-000000000004','Administration entered incorrectly',null)$$,'Treatment correction invalidates linked certificates atomically');
select is((select count(*) from public.vaccine_certificate_events where kind='treatment_corrected'),2::bigint,'Both issued snapshots retain correction evidence');
select is(jsonb_array_length(public.read_vaccine_certificate('49000000-0000-4000-8000-000000000005')->'events'),2,'Print bundle includes supersession and correction events');
select ok(not ((public.read_vaccine_certificate('49000000-0000-4000-8000-000000000005')->'certificate') ? 'request'),'Print bundle omits internal retry request');
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000004',(select v from requests where k='details'))$$,'23514','Corrected vaccination cannot be certified','Corrected treatment cannot issue');
select public.record_patient_treatment('49000000-0000-4000-8000-000000000009',jsonb_build_object('pet_id',(select id from fx where k='pet'),'historical',true,'quantity',1,'product_name','External vaccine','manufacturer','External maker','lot_number','L','expires_on',current_date+365,'dose','1 mL','route','SC','site','leg','veterinarian','Dr Test','veterinarian_license','TEST-ONLY','administered_at',now(),'source','External original'));
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000009',(select v from requests where k='details'))$$,'23514','Imported history cannot issue a new rabies certificate; retain the original external certificate','Imports do not become new practice rabies certificates');
insert into requests select 'history',public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}');
select is((select jsonb_array_length(v->'vaccinations') from requests where k='history'),1,'General history excludes corrected source');
select is((select v#>'{vaccinations,0,next_due_on}' from requests where k='history'),'null'::jsonb,'Unknown imported due date remains explicitly unknown');
select lives_ok($$select public.issue_vaccine_certificate('49000000-0000-4000-8000-000000000010',(select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}',(select v from requests where k='history'),'Dr Test',true)$$,'General reviewed history certificate can issue');
select public.record_patient_treatment('49000000-0000-4000-8000-000000000011',(select v||jsonb_build_object('administered_at',now()+interval '1 minute') from requests where k='live'));
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'rabies','49000000-0000-4000-8000-000000000011',(select v from requests where k='details'))$$,'23514','A future administration cannot be certified','Future administration cannot issue rabies proof');
select set_config('request.jwt.claims','{"sub":"48000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.preview_vaccine_certificate((select id from fx where k='pet'),'vaccine_history',null,'{"due_plan_review_version":2}')$$,'42501','Certificate issuance requires an authorized veterinarian','Non-DVM staff cannot issue');
select is((select count(*) from public.vaccine_certificates),3::bigint,'Active staff can read issued history');
reset role;
select set_config('request.jwt.claims','{}',true);
update public.profiles set is_active=false where id='48000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"48000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.vaccine_certificates),0::bigint,'Inactive staff cannot read certificates');
set local role anon;
select throws_ok($$select * from public.vaccine_certificates$$,'42501',null,'Anonymous access denied');
reset role;
select throws_ok($$update public.vaccine_certificates set signature_name='Tampered'$$,'23514','Certificate history is immutable; void or reissue with a reason','Immutable trigger also guards privileged accidental updates');
select ok(exists(select 1 from public.audit_logs where table_name='vaccine_certificates' and user_id='48000000-0000-4000-8000-000000000001'),'Issued certificates audited with real actor');
select * from finish();
rollback;
